:root { --p06-col: 52rem; --p06-area-min: clamp(8rem, 38cqh, 18rem); --p06-room: 2rem; --p06-combo-room: 3.25rem; --p06-tab-end: 1.5rem; --p06-menu-min: 10rem; --p06-menu-rest: 7rem; }
.p06-wrap { max-width: var(--p06-col); margin-inline: auto; display: grid; gap: var(--s-3); margin-top: calc(var(--p06-scroll, 0rem) * -1); }
.p06-top { display: grid; gap: var(--s-2); }
.p06-form { display: grid; gap: var(--s-4); }
.p06-form .field__head { display: flex; flex-wrap: wrap; align-items: baseline; justify-content: flex-start; column-gap: var(--s-2); }
.p06-pos { position: relative; }
.p06-ph { color: var(--muted); }
.p06-form .select[aria-invalid="true"] { border-color: var(--terra); outline: var(--w1) solid var(--terra); outline-offset: calc(var(--w1) * -2); }
.p06-form .select.p06-focus { border-color: var(--blue); outline: var(--w1) solid var(--blue); outline-offset: calc(var(--w1) * -2); }
.p06-combo { position: relative; }
.p06-combo .textarea { padding-inline-end: var(--p06-combo-room); }
.p06-combo__btn { position: absolute; inset-block-start: 0; inset-inline-end: var(--w2); }
.p06-name { min-height: var(--ctl-h); resize: none; field-sizing: content; }
.p06-area { position: relative; }
.p06-area .textarea { min-height: var(--p06-area-min); resize: none; }
.field__count.is-over { color: var(--ink); font-weight: var(--fw-bold); }
.p06-focus { border-color: var(--blue); outline: var(--w1) solid var(--blue); outline-offset: calc(var(--w1) * -2); }
.p06-e { --frame-w: var(--w2); }
.p06-ro { display: grid; }
.rec.p06-roc { grid-template-columns: minmax(0, 1fr); grid-template-areas: "body"; padding-inline: 0; border-top: var(--w1) solid var(--rule); }
.p06-actions { display: flex; flex-wrap: wrap; justify-content: center; gap: var(--s-2); }
.p06-actions > .btn { flex: 1 1 0; }
.p06-actions--3 { display: grid; gap: var(--s-3); }
.p06-main { display: flex; gap: var(--s-2); }
.p06-main > * { flex: 1 1 0; }
@media (min-width: 48rem) and (min-height: 31.25rem) {
  .p06-actions > .btn { flex: none; }
  .p06-actions--3 { grid-template-columns: 1fr auto 1fr; align-items: center; }
  .p06-actions--3 > .p06-del { justify-self: start; }
  .p06-main > * { flex: none; }
}
.p06-tipwrap { display: flex; justify-content: center; }
.p06-actions .btn .spinner { width: var(--icon-sm); height: var(--icon-sm); }
.p06-deleted { display: grid; justify-items: center; gap: var(--s-3); padding: var(--s-4) 0; }
.p06-deleted .banner { width: 100%; justify-content: center; text-align: center; }
.p06-app .tabwrap > .tab { padding-inline: var(--s-1) var(--p06-tab-end); }
.p06-app .tab__help { inset-inline-end: var(--w2); }
.dialog__foot.p06-foot { flex-direction: column; }
.p06-foot > * { flex: none; }
.p06-pop { position: absolute; inset-inline: 0; top: calc(100% + var(--s-1)); z-index: 20; }
.p06-list { display: flex; flex-direction: column; gap: var(--s-1); padding: var(--s-1); margin: calc(var(--s-1) * -1); max-height: max(var(--p06-menu-min), calc(100cqh - var(--p06-menu-rest))); overflow: auto; }
.p06-list > * { flex: none; }
.p06-opt { padding-block: var(--s-2); text-align: start; }
.p06-opt__body { display: grid; min-width: 0; }
.p06-opt__t { font-weight: var(--fw-bold); overflow-wrap: anywhere; }
.p06-opt__d { font-size: var(--fs-small); line-height: var(--lh-small); font-weight: var(--fw-regular); color: var(--muted); overflow-wrap: anywhere; }
.p06-opt[aria-disabled="true"] .p06-opt__d { color: var(--c-disabled-text); }
.p06-opt--plain { min-height: var(--row-h); }
.p06-kfocus { outline: var(--focus-ring); outline-offset: var(--focus-offset); }

.brand { min-height: var(--hit); }
.emo { width: 1.125em; height: 1.125em; flex: none; vertical-align: -0.2em; fill: none; stroke: currentColor; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; }
@media (min-width: 37.5rem) and (max-height: 31.1875rem) { .tab { padding-inline: var(--s-1); } }
